<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\ReviewWorkflow;use App\Support\Url;Auth::requirePermission('LOAD_REVIEW_QUEUE_VIEW');$loads=ReviewWorkflow::queue();$pageTitle='Operations Load Queue';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Operations Load Queue</h1><p>Open submitted, review, and clarification work across customer companies.</p></div><span class="badge"><?=h(count($loads))?> open</span></div><div class="card table-wrap"><table><thead><tr><th>Reference</th><th>Company</th><th>Cargo</th><th>Route</th><th>Version</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($loads as $l):?><tr><td><?=h($l['load_ref'])?></td><td><?=h($l['company_name'])?></td><td><?=h($l['cargo_summary'])?></td><td><?=h($l['origin_city'].' → '.$l['destination_city'])?></td><td>v<?=h($l['version_no'])?></td><td><span class="status-pill"><?=h(str_replace('_',' ',$l['current_status']))?></span></td><td><a href="<?=h(Url::to('operations/review.php?id='.$l['load_id']))?>">Review</a></td></tr><?php endforeach;if(!$loads):?><tr><td colspan="7" class="muted">No submitted or active reviews.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
